<template><div class="page"><div class="page-header"><div><el-button link @click="router.back()"><ArrowLeft/>返回题库</el-button><h1 class="page-title">题目 #{{question.id}}</h1><p class="page-description">查看、编辑并审核题目及其知识库来源。</p></div><div><el-button :loading="reviewing" @click="aiReview"><MagicStick/>AI重新审核</el-button><el-button v-if="!editing" type="primary" @click="editing=true">编辑题目</el-button></div></div><PageState :loading="loading" :error="error" @retry="load"><div class="split-layout"><section class="card card-body"><div class="toolbar"><StatusTag :value="question.review_status"/><el-tag>{{question.question_type}}</el-tag><el-tag type="info">{{question.difficulty}}</el-tag><span>{{question.score}} 分</span></div><template v-if="!editing"><h2 class="question-stem"><MathText :text="question.stem"/></h2><div v-for="o in question.options" :key="o.id" class="question-option" :class="{correct:o.is_correct}">{{o.label}}. <MathText :text="o.content"/></div><div class="analysis-box"><b>参考答案：</b><MathText :text="(question.answer||[]).join('、')"/><br><b>解析：</b><MathText :text="question.analysis||'暂无解析'"/><br><b>评分要点：</b><MathText :text="(question.scoring_points||[]).join('；')||'无'"/></div></template><el-form v-else label-position="top"><el-form-item label="题干"><el-input v-model="form.stem" type="textarea" :rows="4"/></el-form-item><el-form-item label="选项" v-if="['single_choice','multiple_choice'].includes(form.question_type)"><div v-for="o in form.options" :key="o.label" class="option-edit"><el-input v-model="o.content"><template #prepend>{{o.label}}</template></el-input></div></el-form-item><div class="form-grid"><el-form-item label="答案"><el-select v-model="form.answer" multiple allow-create filterable style="width:100%"/></el-form-item><el-form-item label="分值"><el-input-number v-model="form.score" :min=".5" :step=".5"/></el-form-item><el-form-item label="难度"><el-select v-model="form.difficulty"><el-option v-for="x in ['简单','较易','中等','较难','困难']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="解析" class="full"><el-input v-model="form.analysis" type="textarea" :rows="4"/></el-form-item></div><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存修改</el-button></el-form></section><aside><div class="card card-body"><h3>知识库来源</h3><p>{{question.source_summary||'未记录来源摘要'}}</p><div class="muted">来源文本块：{{(question.source_chunk_ids||[]).join('、')||'未关联'}}</div><div class="muted">生成模型：{{question.generation_model||'人工创建'}}</div></div><div class="card card-body" style="margin-top:18px"><h3>审核记录</h3><div v-for="r in question.reviews" :key="r.id" class="review"><StatusTag :value="r.passed?'APPROVED':'NEEDS_REVISION'"/> {{r.review_type}} · {{r.score}}分<p v-if="r.issues?.length">问题：{{r.issues.join('；')}}</p><p v-if="r.suggestions?.length">建议：{{r.suggestions.join('；')}}</p></div><div class="actions"><el-button type="success" @click="status('approve')">审核通过</el-button><el-button type="warning" @click="status('revision')">退回修改</el-button><el-button type="danger" plain @click="status('reject')">审核不通过</el-button></div></div></aside></div></PageState></div></template>
<script setup>import{ref,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{questionsApi}from'../../api';import PageState from'../../components/PageState.vue';import StatusTag from'../../components/StatusTag.vue';import MathText from'../../components/MathText.vue';const route=useRoute(),router=useRouter(),question=ref({}),form=ref({}),loading=ref(true),error=ref(''),editing=ref(false),saving=ref(false),reviewing=ref(false);const load=async()=>{loading.value=true;try{question.value=await questionsApi.get(route.params.id);form.value=JSON.parse(JSON.stringify(question.value))}catch(e){error.value=e.message}finally{loading.value=false}};const save=async()=>{saving.value=true;try{question.value=await questionsApi.update(question.value.id,form.value);editing.value=false;ElMessage.success('题目已保存');load()}finally{saving.value=false}};const status=async name=>{await questionsApi[name](question.value.id);ElMessage.success('审核状态已更新');load()};const aiReview=async()=>{reviewing.value=true;try{await questionsApi.aiReview(question.value.id);ElMessage.success('AI审核完成');load()}finally{reviewing.value=false}};onMounted(load)</script><style scoped>.option-edit{margin:8px 0;width:100%}.review{padding:12px 0;border-bottom:1px solid var(--border)}.review p{font-size:13px;color:var(--text-secondary)}.actions{display:flex;gap:8px;margin-top:16px;flex-wrap:wrap}</style>
